import{_ as o,o as e,c as d,a2 as a}from"./chunks/framework.G0y0PQA7.js";const r="/relio/shots/ko/ai-change-notice.png",l="/relio/shots/ko/ai-connected.png",i="/relio/shots/ko/ai-first-notice.png",c="/relio/shots/ko/ai-prefs.png",s="/relio/shots/ko/ai-proposal-merge.png",n="/relio/shots/ko/ai-tools-menu.png",p="/relio/shots/ko/ai-copy-location.png",f=JSON.parse('{"title":"AI와 함께 쓰기","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai.md","filePath":"features/ai.md"}'),h={name:"features/ai.md"};function u(g,t,m,A,b,I){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="ai와-함께-쓰기" tabindex="-1">AI와 함께 쓰기 <a class="header-anchor" href="#ai와-함께-쓰기" aria-label="Permalink to &quot;AI와 함께 쓰기&quot;">​</a></h1><p>Claude Code · Claude Desktop · Cursor 같은 <strong>내 AI 도구</strong>에 말로 요청해 Relio 모델을 읽고, 요구사항 문서로 새 초안을 만들고, 열린 모델을 고치는 방법을 설명합니다.</p><h2 id="무엇인가요" tabindex="-1">무엇인가요 <a class="header-anchor" href="#무엇인가요" aria-label="Permalink to &quot;무엇인가요&quot;">​</a></h2><ul><li>AI 도구에 주소(URL)를 넣는 것이 아니라, <strong>프로그램 <code>relio mcp</code>를 AI 도구에 한 번 등록</strong>합니다. AI 도구가 필요할 때 내 PC에서 <code>relio mcp</code>를 띄워 주고받습니다(로컬 MCP 서버).</li><li>모든 것이 <strong>내 PC 안</strong>에서 일어납니다. Relio 자체에는 AI가 없고, 네트워크 접속 · 로그인 · Relio 서버가 없습니다. 질문에 답하고 글을 쓰는 것은 내가 쓰는 AI 도구입니다.</li><li>AI가 고친 것은 <strong>Relio 창의 열린 문서에 바로 반영</strong>됩니다(저장 전). 되돌리기 한 번으로 돌아가고, <strong>파일은 내가 저장할 때만</strong> 바뀝니다.</li></ul><h2 id="처음-쓰는-순서" tabindex="-1">처음 쓰는 순서 <a class="header-anchor" href="#처음-쓰는-순서" aria-label="Permalink to &quot;처음 쓰는 순서&quot;">​</a></h2><ol><li><p><strong>등록(처음 한 번)</strong> — AI 도구를 켜기 전에 터미널에서 아래 한 줄을 붙여 넣습니다. <code>claude mcp list</code>에 <code>relio</code>가 보이면 된 것입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp add --scope user relio -- relio mcp</span></span></code></pre></div><p><code>relio</code>가 PATH에 없으면 아래 <a href="#relio가-path에-없을-때">relio가 PATH에 없을 때</a>를 보세요. 도구 › <strong>명령줄·AI 연결…</strong> 창에서 이 줄을 골라 복사할 수도 있습니다.</p></li><li><p><strong>AI 도구를 새로 켭니다</strong> — 등록은 새로 켠 AI 도구부터 보입니다. Claude Code는 모델이 있는 폴더에서 <code>claude</code>로 켭니다.</p></li><li><p><strong>AI 도구 안에서 첫 요청</strong> — 예를 들어 이렇게 쳐 봅니다.</p><blockquote><p>Relio로 shop.erm의 테이블 구성을 설명해 줘</p></blockquote></li></ol><p>Relio를 말하지 않아도 대개 <code>.erm</code> · 테이블 · 컬럼 · 인덱스에 관한 요청이면 AI 도구가 알아서 Relio 도구를 씁니다.</p><h2 id="할-수-있는-것" tabindex="-1">할 수 있는 것 <a class="header-anchor" href="#할-수-있는-것" aria-label="Permalink to &quot;할 수 있는 것&quot;">​</a></h2><h3 id="_1-요구사항-문서로-erd-초안-만들기" tabindex="-1">① 요구사항 문서로 ERD 초안 만들기 <a class="header-anchor" href="#_1-요구사항-문서로-erd-초안-만들기" aria-label="Permalink to &quot;① 요구사항 문서로 ERD 초안 만들기&quot;">​</a></h3><blockquote><p>이 폴더의 요구사항 문서를 읽고 ERD 초안을 만들어 Relio에 열어 줘</p></blockquote><p>AI가 문서를 읽고 <strong>새</strong> <code>.erm</code> 초안을 만들어 Relio에 바로 엽니다. 이미 있는 파일은 덮어쓰지 않고, AI 도구가 지금 쓰는 폴더 밖에는 새 파일을 만들지 않습니다. 홈 폴더에서 AI 도구를 켰다면 어느 프로젝트 폴더에 만들지 먼저 묻습니다. Claude Code에서는 추천 질문 <code>/mcp__relio__draft_from_requirements</code>로도 시작할 수 있습니다.</p><h3 id="_2-열린-모델-고치기" tabindex="-1">② 열린 모델 고치기 <a class="header-anchor" href="#_2-열린-모델-고치기" aria-label="Permalink to &quot;② 열린 모델 고치기&quot;">​</a></h3><blockquote><p>선택한 테이블에 감사 컬럼을 추가해 줘</p></blockquote><ul><li>Relio 창에서 테이블을 골라 두고 &quot;선택한 테이블에…&quot;라고 말하면 AI가 어느 테이블인지 압니다.</li><li>AI가 고친 것은 열린 문서에 <strong>바로 들어갑니다</strong>. 대상 파일이 열려 있지 않으면 열고, Relio가 꺼져 있으면 켭니다.</li><li>바뀐 테이블이 잠깐 강조되고 <strong>&quot;AI가 ORDERS 외 2개를 바꿨습니다 [되돌리기] [바뀐 곳 보기]&quot;</strong> 같은 알림이 뜹니다. <strong>되돌리기</strong> 한 번(또는 <kbd>Ctrl</kbd>+<kbd>Z</kbd>)으로 AI가 바꾸기 전으로 돌아갑니다. 그 뒤에 다른 편집을 했다면 편집 › 되돌리기를 씁니다.</li><li>문서는 &#39;저장 안 됨&#39; 상태가 됩니다. 마음에 들면 직접 저장합니다(<kbd>Ctrl</kbd>+<kbd>S</kbd>).</li><li>저장하지 않은 내 편집과 겹치면 바로 넣지 않고 합치기 탭에서 고르게 합니다. 아래 <a href="#먼저-검토와-합치기-탭">먼저 검토와 합치기 탭</a></li></ul><figure class="shot" data-scene="ai-change-notice"><img src="'+r+`" alt="AI가 바꾼 뒤 — 강조된 테이블과 되돌리기·바뀐 곳 보기 알림" loading="lazy"><figcaption>AI가 바꾼 뒤 — 강조된 테이블과 되돌리기·바뀐 곳 보기 알림</figcaption></figure><h3 id="_3-모델-읽기·설계-검사" tabindex="-1">③ 모델 읽기·설계 검사 <a class="header-anchor" href="#_3-모델-읽기·설계-검사" aria-label="Permalink to &quot;③ 모델 읽기·설계 검사&quot;">​</a></h3><blockquote><p>이 모델을 업무 영역별로 설명해 줘</p></blockquote><blockquote><p>설계 검사 결과를 심각도 순으로 정리해 줘</p></blockquote><p>AI가 모델 요약 · 테이블 · 관계를 읽어 설명하거나, Relio의 <a href="/relio/features/check">설계 검사</a>를 돌려 오류 · 경고 · 참고를 심각도 순으로 정리합니다. 앱의 문제 목록과 같은 규칙입니다. 읽기만 하는 요청은 파일을 바꾸지 않습니다.</p><h2 id="등록하기" tabindex="-1">등록하기 <a class="header-anchor" href="#등록하기" aria-label="Permalink to &quot;등록하기&quot;">​</a></h2><h3 id="연결-범위" tabindex="-1">연결 범위 <a class="header-anchor" href="#연결-범위" aria-label="Permalink to &quot;연결 범위&quot;">​</a></h3><p>Claude Code는 등록할 때 범위를 고릅니다. 범위는 <strong>어느 폴더에서 AI 도구를 켤 때 Relio가 연결되는지</strong>입니다(Claude Code의 등록 방식입니다). AI가 볼 수 있는 파일과는 별개입니다 — 아래 <a href="#ai가-볼-수-있는-파일">AI가 볼 수 있는 파일</a></p><table tabindex="0"><thead><tr><th>범위</th><th>뜻</th><th>등록 줄</th></tr></thead><tbody><tr><td>모든 폴더에서 <code>user</code> (권장)</td><td>어느 폴더에서 AI 도구를 켜도 연결됩니다.</td><td><code>claude mcp add --scope user relio -- relio mcp</code></td></tr><tr><td>이 프로젝트 폴더에서만 <code>local</code></td><td>그 프로젝트 폴더의 터미널에서 붙여 넣습니다.</td><td><code>claude mcp add --scope local relio -- relio mcp</code></td></tr><tr><td>팀과 함께 <code>project</code></td><td>그 폴더에 <code>.mcp.json</code>이 생기고, 커밋하면 팀원도 연결됩니다. 팀원도 각자 Relio를 설치하고 명령줄(<code>relio</code>)을 켜야 하며, Claude Code가 처음 쓸 때 허락을 묻습니다. 팀원마다 설치 경로가 다르므로 늘 <code>relio mcp</code> 꼴로 씁니다.</td><td><code>claude mcp add --scope project relio -- relio mcp</code></td></tr></tbody></table><p>도구 › <strong>명령줄·AI 연결…</strong> 창에서 범위를 고르면 그 범위의 등록 줄을 복사할 수 있습니다.</p><h3 id="claude-desktop-·-cursor" tabindex="-1">Claude Desktop · Cursor <a class="header-anchor" href="#claude-desktop-·-cursor" aria-label="Permalink to &quot;Claude Desktop · Cursor&quot;">​</a></h3><p>Claude Desktop · Cursor는 터미널 명령이 아니라 설정 파일에 적습니다. 두 앱은 같은 꼴입니다.</p><table tabindex="0"><thead><tr><th>AI 도구</th><th>설정 파일</th></tr></thead><tbody><tr><td>Claude Desktop</td><td><code>claude_desktop_config.json</code></td></tr><tr><td>Cursor</td><td><code>.cursor/mcp.json</code></td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{ &quot;mcpServers&quot;: { &quot;relio&quot;: { &quot;command&quot;: &quot;relio&quot;, &quot;args&quot;: [&quot;mcp&quot;, &quot;--root&quot;, &quot;C:\\\\work\\\\models&quot;] } } }</span></span></code></pre></div><ul><li>이 앱들은 내 모델 폴더가 아닌 곳에서 <code>relio mcp</code>를 띄우므로 <strong><code>--root</code>로 모델 폴더를 꼭 적습니다</strong>.</li><li>JSON 안에서는 <code>\\</code>를 <code>\\\\</code>로 두 번 씁니다. 옵션은 <code>args</code>에 하나씩 넣습니다.</li><li>등록한 뒤에는 그 앱을 다시 켭니다.</li></ul><h3 id="relio가-path에-없을-때" tabindex="-1">relio가 PATH에 없을 때 <a class="header-anchor" href="#relio가-path에-없을-때" aria-label="Permalink to &quot;relio가 PATH에 없을 때&quot;">​</a></h3><p>설치할 때 **&quot;명령줄에서 relio 쓰기&quot;**를 켜지 않았거나 설치 없이 쓰는 실행판이면 <code>relio</code>가 PATH에 없습니다. 그럴 때는 <code>relio</code> 자리에 실행 파일의 전체 경로를 넣습니다. 도움말 › Relio 정보나 도구 › 명령줄·AI 연결… 창의 <strong>명령줄 경로 복사</strong>를 누르면 지금 쓰는 실행 파일의 전체 경로가 따옴표째 복사됩니다. <code>relio mcp --help</code>도 PATH에 없을 때 그 실행 파일의 등록 줄을 보여 줍니다. <a href="/relio/features/cli#시작하기">명령줄 › 시작하기</a></p><p>운영 체제에 따라 다른 것은 아래 표에 모았습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>Windows</th></tr></thead><tbody><tr><td>설치한 실행 파일(기본 위치)</td><td><code>%LOCALAPPDATA%\\Relio\\relio.exe</code></td></tr><tr><td>Claude Code 등록</td><td><code>claude mcp add --scope user relio -- &lt;복사한 전체 경로&gt; mcp</code> (명령줄 경로 복사로 얻은, 따옴표가 붙은 경로)</td></tr><tr><td>JSON 설정의 <code>command</code></td><td>복사한 경로에서 바깥 따옴표를 빼고 <code>\\</code>를 <code>\\\\</code>로 바꿔 넣습니다(예: <code>&quot;D:\\\\Tools\\\\Relio\\\\relio.exe&quot;</code>).</td></tr><tr><td>나중에 PATH 켜기</td><td>설치 파일을 다시 실행해 마침 페이지의 세 번째 칸 **&quot;명령줄에서 relio 쓰기&quot;**를 켭니다. 실행판(zip)은 그 폴더를 PATH에 직접 더합니다.</td></tr><tr><td>켠 뒤</td><td>이미 켜져 있던 터미널 · Claude Desktop · Cursor는 다시 켜야 <code>relio</code>를 찾습니다.</td></tr><tr><td>&quot;AI 도구에서 열기…&quot;가 여는 터미널</td><td>Windows Terminal, 없으면 PowerShell</td></tr></tbody></table><h3 id="옵션" tabindex="-1">옵션 <a class="header-anchor" href="#옵션" aria-label="Permalink to &quot;옵션&quot;">​</a></h3><p>옵션은 <code>relio mcp</code> 뒤에 붙입니다. 예: <code>claude mcp add --scope user relio -- relio mcp --root &quot;C:\\work\\models&quot; --anonymize</code></p><table tabindex="0"><thead><tr><th>옵션</th><th>하는 일</th></tr></thead><tbody><tr><td><code>--root &lt;폴더&gt;</code></td><td>AI가 볼 수 있는 폴더를 더합니다. 여러 번 줄 수 있습니다. 주지 않으면 AI 도구를 켠 지금 폴더입니다.</td></tr><tr><td><code>--anonymize</code></td><td>테이블 · 컬럼 등의 이름을 <code>T1</code> · <code>C1</code> 같은 번호로 바꾸고 설명 · 노트 · 기본값을 비운 모델로만 답합니다. 형식 · 길이 · 키 · 관계 구조와 파일 이름은 그대로 전달됩니다. 쓰기 도구는 빠집니다.</td></tr><tr><td><code>--read-only</code></td><td>쓰기 도구(<code>create_draft</code> · <code>propose_change</code>)를 뺍니다. 읽은 내용은 그대로 전송됩니다.</td></tr></tbody></table><h2 id="ai가-볼-수-있는-파일" tabindex="-1">AI가 볼 수 있는 파일 <a class="header-anchor" href="#ai가-볼-수-있는-파일" aria-label="Permalink to &quot;AI가 볼 수 있는 파일&quot;">​</a></h2><ol><li><strong>Relio에 열려 있는 <code>.erm</code> 파일</strong> — 어느 폴더에 있든, AI 도구를 어디서 켜든 읽고 고칠 수 있습니다. 그 파일 하나만 허락되고, 같은 폴더의 다른 파일이나 그 옆에 새 파일을 쓰는 것은 허락되지 않습니다. Relio에서 닫으면 다시 쓸 수 없습니다.</li><li><strong>AI 도구를 켠 폴더</strong>와 그 아래 <code>.erm</code> 파일</li><li><strong><code>--root</code>로 더한 폴더</strong></li></ol><p>허락하지 않는 폴더도 있습니다. 이런 폴더를 <code>--root</code>로 주거나 그 폴더에서 AI 도구를 켜면 그 폴더는 허락하지 않습니다.</p><table tabindex="0"><thead><tr><th>허락하지 않는 폴더</th><th>Windows</th></tr></thead><tbody><tr><td>드라이브 맨 위</td><td><code>C:\\</code></td></tr><tr><td>사용자 홈 맨 위와 그 위</td><td>홈 폴더 맨 위, <code>C:\\Users</code></td></tr><tr><td>시스템 폴더와 그 안</td><td>Windows 폴더, Program Files · Program Files (x86) · ProgramData</td></tr><tr><td>네트워크 폴더</td><td>UNC 경로 · 네트워크 드라이브</td></tr></tbody></table><p><strong>홈 폴더에서 AI 도구를 켜도 연결은 되고, Relio에 열린 파일만 보입니다.</strong> 폴더 전체를 쓰려면 <code>.erm</code>이 있는 프로젝트 폴더에서 다시 켜거나 <code>--root &lt;폴더&gt;</code>로 등록하세요.</p><h2 id="등록-지우기" tabindex="-1">등록 지우기 <a class="header-anchor" href="#등록-지우기" aria-label="Permalink to &quot;등록 지우기&quot;">​</a></h2><p>등록한 범위에 맞춰 지웁니다. 지워도 Relio 앱과 파일은 그대로입니다.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude mcp remove relio --scope user</span></span>
<span class="line"><span>claude mcp list</span></span></code></pre></div><p><code>local</code> · <code>project</code>로 등록했다면 그 프로젝트 폴더에서 <code>--scope local</code> · <code>--scope project</code>로 지웁니다. <code>claude mcp list</code>에 <code>relio</code>가 없으면 지워진 것입니다.</p><h2 id="창에서-보이는-것" tabindex="-1">창에서 보이는 것 <a class="header-anchor" href="#창에서-보이는-것" aria-label="Permalink to &quot;창에서 보이는 것&quot;">​</a></h2><ul><li><strong>AI 연결됨</strong> — AI 도구가 연결되어 있으면 상태 표시줄 오른쪽에 보입니다. AI 도구가 끝나면(비정상 종료 포함) 곧 사라집니다.</li><li><strong>처음 연결 알림</strong> — 처음 연결된 때 한 번 &quot;AI 도구 연결&quot; 창이 떠서, AI가 바꾼 내용이 창에 바로 들어가고 파일은 저장할 때만 바뀐다는 것, AI가 읽은 모델 내용이 그 AI 서비스로 전송된다는 것을 알립니다. <strong>설명서 보기</strong>로 앱 안 설명서의 이 절을 엽니다.</li><li><strong>바로 반영 알림</strong> — AI가 고치면 바뀐 테이블이 잠깐 강조되고 <strong>되돌리기</strong> · <strong>바뀐 곳 보기</strong>가 있는 알림이 뜹니다. 위 <a href="#_2-열린-모델-고치기">② 열린 모델 고치기</a></li><li><strong>바깥 변경 다시 읽기</strong> — AI가 연결되어 있는 동안 열린 파일이 바깥에서 바뀌면(AI 도구가 아닌 다른 프로그램의 변경도 포함), 저장하지 않은 수정이 없을 때는 묻지 않고 다시 읽습니다. 바뀐 테이블을 3초 강조하고 상태 표시줄에 &quot;AI 변경 반영: ORDERS 외 2&quot; 같은 한 줄을 띄웁니다. 이 줄을 누르면 그 테이블로 갑니다. 저장하지 않은 수정이 있으면 다시 읽지 않고 지금처럼 **합치기…**를 묻습니다. <a href="/relio/features/file#창으로-돌아왔을-때">파일 › 창으로 돌아왔을 때</a></li></ul><figure class="shot" data-scene="ai-connected"><img src="`+l+'" alt="상태 표시줄 오른쪽의 AI 연결됨" loading="lazy"><figcaption>상태 표시줄 오른쪽의 AI 연결됨</figcaption></figure><figure class="shot" data-scene="ai-first-notice"><img src="'+i+'" alt="처음 연결 때 뜨는 AI 도구 연결 알림 창" loading="lazy"><figcaption>처음 연결 때 뜨는 AI 도구 연결 알림 창</figcaption></figure><h3 id="먼저-검토와-합치기-탭" tabindex="-1">먼저 검토와 합치기 탭 <a class="header-anchor" href="#먼저-검토와-합치기-탭" aria-label="Permalink to &quot;먼저 검토와 합치기 탭&quot;">​</a></h3><p>AI 변경은 기본으로 바로 반영되지만, 아래 경우에는 합치기 탭 **&quot;합치기: &lt;파일&gt; — AI 변경안&quot;**으로 열려 내가 골라 <strong>적용</strong>합니다.</p><ul><li>저장하지 않은 내 편집과 AI 변경이 겹칠 때</li><li>셀 편집 · 끌기 · 대화 창이 10초 넘게 이어질 때(그보다 짧으면 끝날 때까지 기다렸다가 반영합니다)</li><li>도구 › 환경 설정 › 일반 › <strong>AI 도구</strong>의 <strong>AI 변경</strong>을 <strong>먼저 검토</strong>로 골랐을 때(기본은 <strong>바로 반영</strong>) — 늘 합치기 탭으로 엽니다</li></ul><p>합치기 탭의 바탕은 <strong>변경안을 만든 때 파일</strong>, 내 쪽은 열린 문서(저장하지 않은 수정 포함), 바깥 쪽은 AI 변경안입니다. 받을 것을 고르고 적용하는 방법은 <a href="/relio/features/git#합치기-탭">Git과 합치기 › 합치기 탭</a>과 같습니다. 변경안 사본은 설정 폴더의 <code>mcp\\proposals</code>에 두고 7일 뒤 앱을 켤 때 지웁니다.</p><figure class="shot" data-scene="ai-prefs"><img src="'+c+'" alt="환경 설정 › 일반 › AI 도구 — 바로 반영·먼저 검토" loading="lazy"><figcaption>환경 설정 › 일반 › AI 도구 — 바로 반영·먼저 검토</figcaption></figure><figure class="shot" data-scene="ai-proposal-merge"><img src="'+s+'" alt="합치기 탭 — AI 변경안에서 받을 항목 고르기" loading="lazy"><figcaption>합치기 탭 — AI 변경안에서 받을 항목 고르기</figcaption></figure><h2 id="도구-메뉴" tabindex="-1">도구 메뉴 <a class="header-anchor" href="#도구-메뉴" aria-label="Permalink to &quot;도구 메뉴&quot;">​</a></h2><table tabindex="0"><thead><tr><th>메뉴 › 항목</th><th>하는 일</th></tr></thead><tbody><tr><td>도구 › AI 도구에서 열기…</td><td>지금 파일이 있는 폴더에서 터미널을 열고, 등록 줄 · AI 도구 켜기 · 첫 요청을 복사할 수 있게 보여 줍니다. 아래 &quot;AI 도구에서 열기&quot;</td></tr><tr><td>도구 › 명령줄·AI 연결…</td><td>연결 상태, 반영 방식, 연결 범위와 등록 · 지우기 줄, 명령줄 상태를 한곳에서 봅니다. 아래 &quot;명령줄·AI 연결 창&quot;</td></tr><tr><td>도구 › 현재 파일 경로 복사</td><td>지금 파일의 전체 경로를 따옴표째 복사합니다. 문서 탭 오른쪽 클릭의 <strong>경로 복사</strong>와 같습니다.</td></tr><tr><td>도구 › 환경 설정…</td><td><a href="/relio/features/preferences">환경 설정</a></td></tr></tbody></table><p>AI 도구에서 열기와 현재 파일 경로 복사는 저장된 파일에서만 씁니다(새 문서 · 샘플 사본에서는 꺼짐).</p><figure class="shot" data-scene="ai-tools-menu"><img src="'+n+'" alt="도구 메뉴 — AI 도구에서 열기·명령줄·AI 연결·현재 파일 경로 복사" loading="lazy"><figcaption>도구 메뉴 — AI 도구에서 열기·명령줄·AI 연결·현재 파일 경로 복사</figcaption></figure><h3 id="ai-도구에서-열기" tabindex="-1">AI 도구에서 열기 <a class="header-anchor" href="#ai-도구에서-열기" aria-label="Permalink to &quot;AI 도구에서 열기&quot;">​</a></h3><p>도구 › <strong>AI 도구에서 열기…</strong>(문서 탭 오른쪽 클릭에도 있음)는 그 <code>.erm</code>이 있는 폴더에서 터미널을 <strong>열기만</strong> 합니다. 어떤 명령도 대신 실행하지 않습니다. &quot;AI 도구에서 열기&quot; 창에는 순서대로 다음이 <strong>복사</strong> 단추와 함께 보입니다.</p><ol><li><strong>터미널에 붙여 넣기</strong> — 등록 줄(처음 한 번만). 창이 열릴 때 클립보드에 미리 들어 있습니다. 명령줄·AI 연결 창에서 고른 범위를 따릅니다.</li><li><strong>AI 도구 켜기</strong> — Claude Code는 <code>claude</code>로 켭니다.</li><li><strong>AI 도구 안에서 첫 요청</strong> — 예: &quot;Relio로 &lt;파일&gt;의 테이블 구성을 설명해 줘&quot;. 다른 예로 요구사항 문서로 초안을 만드는 요청도 보입니다.</li></ol><p>터미널을 열지 못하면 그 폴더 경로를 보여 주니 직접 터미널을 여세요.</p><h3 id="명령줄·ai-연결-창" tabindex="-1">명령줄·AI 연결 창 <a class="header-anchor" href="#명령줄·ai-연결-창" aria-label="Permalink to &quot;명령줄·AI 연결 창&quot;">​</a></h3><p>도구 › **명령줄·AI 연결…**에서 보는 것입니다.</p><ul><li><strong>AI 연결</strong> — 연결 상태(AI 연결됨 · 연결 없음), AI 변경 반영 방식(바로 반영 · 먼저 검토 — 바꾸는 곳은 환경 설정 › 일반), 연결 범위(모든 폴더에서 · 이 프로젝트 폴더에서만 · 팀과 함께), 고른 범위의 등록 줄 · 등록 지우기 줄 · 등록됐는지 확인(<code>claude mcp list</code>).</li><li><strong>명령줄</strong> — &quot;명령줄에서 relio 쓰기&quot;가 켜짐인지 꺼짐인지, 명령줄 경로와 <strong>명령줄 경로 복사</strong>. 꺼짐이면 켜는 방법을 알려 줍니다(위 <a href="#relio가-path에-없을-때">relio가 PATH에 없을 때</a>).</li></ul><h3 id="파일·위치-넘겨주기" tabindex="-1">파일·위치 넘겨주기 <a class="header-anchor" href="#파일·위치-넘겨주기" aria-label="Permalink to &quot;파일·위치 넘겨주기&quot;">​</a></h3><p>AI에게 어느 파일 · 어느 테이블인지 정확히 알려 주고 싶으면 복사해서 AI 도구에 붙여 넣습니다.</p><ul><li>도구 › <strong>현재 파일 경로 복사</strong> — 지금 파일의 경로</li><li>캔버스나 아웃라인에서 테이블 · 뷰를 오른쪽 클릭 › <strong>AI용 위치 복사</strong> — <code>&quot;…\\shop.erm&quot;의 ORDERS 테이블</code> 같은 한 줄</li></ul><p>모델이 여럿인데 어느 파일인지 말하지 않으면 AI가 먼저 묻습니다.</p><figure class="shot" data-scene="ai-copy-location"><img src="'+p+'" alt="테이블 오른쪽 클릭 메뉴의 AI용 위치 복사" loading="lazy"><figcaption>테이블 오른쪽 클릭 메뉴의 AI용 위치 복사</figcaption></figure><h2 id="ai가-쓰는-도구" tabindex="-1">AI가 쓰는 도구 <a class="header-anchor" href="#ai가-쓰는-도구" aria-label="Permalink to &quot;AI가 쓰는 도구&quot;">​</a></h2><p>AI 도구가 알아서 골라 씁니다. 직접 부를 필요는 없습니다.</p><table tabindex="0"><thead><tr><th>도구</th><th>하는 일</th></tr></thead><tbody><tr><td><code>list_models</code></td><td>허락한 폴더의 <code>.erm</code>과 Relio에 열린 파일 목록(파일마다 출처 표시)</td></tr><tr><td><code>model_summary</code></td><td>DB · 개수 · 카테고리 · 테이블 목록 · 설계 검사 지적 수</td></tr><tr><td><code>list_tables</code></td><td>테이블 · 뷰 목록</td></tr><tr><td><code>get_table</code></td><td>한 테이블의 컬럼 · 인덱스 · 관계 전체</td></tr><tr><td><code>find</code></td><td>이름 · 설명 찾기(초성 포함)</td></tr><tr><td><code>related</code></td><td>관계로 이어진 테이블(깊이 3까지)</td></tr><tr><td><code>lint</code></td><td>설계 검사</td></tr><tr><td><code>export_ddl</code></td><td>DDL 글</td></tr><tr><td><code>diff</code></td><td>다른 파일이나 Git 버전과 비교</td></tr><tr><td><code>get_selection</code></td><td>Relio 창에서 지금 선택한 테이블</td></tr><tr><td><code>open_in_relio</code></td><td>Relio 창에서 열고 테이블을 강조</td></tr><tr><td><code>create_draft</code></td><td>DBML · Mermaid · SQL로 <strong>새</strong> <code>.erm</code> 초안을 만들고 Relio에 엶(이미 있는 파일은 덮어쓰지 않음)</td></tr><tr><td><code>propose_change</code></td><td>열린 모델 고치기(바로 반영, 또는 합치기 탭)</td></tr></tbody></table><p><code>--read-only</code>·<code>--anonymize</code>에서는 쓰기 도구(<code>create_draft</code>·<code>propose_change</code>)가 빠집니다.</p><p>추천 질문(프롬프트)도 넷 있습니다. AI 도구에서 프롬프트 목록을 고를 수 있으면 보이고, Claude Code에서는 <code>/mcp__relio__&lt;이름&gt;</code>(예: <code>/mcp__relio__explain_model</code>) 슬래시 명령으로 부릅니다.</p><table tabindex="0"><thead><tr><th>추천 질문</th><th>하는 일</th></tr></thead><tbody><tr><td><code>explain_model</code></td><td>모델을 업무 영역별로 설명 — 주요 테이블이 담는 것과 서로의 관계</td></tr><tr><td><code>review_ddl</code></td><td>DDL과 설계를 검토해 문제를 심각도 순으로</td></tr><tr><td><code>change_impact</code></td><td>계획한 변경이 건드리는 테이블 · 관계 · 외래 키를 찾고 작업 순서를 제안</td></tr><tr><td><code>draft_from_requirements</code></td><td>요구사항 문서로 ERD 초안</td></tr></tbody></table><h2 id="안전하게-쓰기" tabindex="-1">안전하게 쓰기 <a class="header-anchor" href="#안전하게-쓰기" aria-label="Permalink to &quot;안전하게 쓰기&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">주의</p><ul><li>AI가 읽은 모델 내용(테이블 · 컬럼 이름과 설명)은 <strong>내 AI 서비스로 전송됩니다</strong>. 처음 연결될 때 한 번 알려 드립니다. 회사 모델이면 <code>--anonymize</code>로 이름 · 설명을 감추고 <code>--root</code>로 폴더를 좁히세요(<code>--read-only</code>는 쓰기만 막고 전송은 막지 않습니다).</li><li>Relio를 거친 AI 변경은 열린 문서에만 들어가고, 파일은 내가 저장할 때만 바뀝니다. Relio가 쓰는 곳은 새 초안 파일과 설정 폴더의 <code>mcp</code> 폴더뿐입니다.</li><li>다만 AI 도구는 Relio와 상관없이 <strong>자기 파일 편집 기능으로 <code>.erm</code>을 직접 고칠 수 있습니다</strong>. 모델 폴더는 백업을 두거나 Git 같은 버전 관리로 지키세요.</li><li>AI는 <strong>저장된 파일</strong>을 읽습니다. 창에서 아직 저장하지 않은 내용은 보지 못합니다(그래서 겹치면 합치기 탭으로 엽니다).</li><li>이름 바꾸기 도구는 없어서, AI가 테이블 · 컬럼 이름을 바꾸면 지우기 + 추가로 반영될 수 있습니다.</li></ul></div><h2 id="자주-묻는-것" tabindex="-1">자주 묻는 것 <a class="header-anchor" href="#자주-묻는-것" aria-label="Permalink to &quot;자주 묻는 것&quot;">​</a></h2><p><strong>터미널에서 등록했는데 Claude 데스크톱 앱의 커넥터 목록에 Relio가 없습니다.</strong> 터미널에서 <code>claude mcp add</code>로 등록한 것은 Claude Code의 등록이라 데스크톱 앱의 커넥터 목록에는 나오지 않습니다. 등록됐는지는 터미널에서 <code>claude mcp list</code>로 확인합니다.</p><p><strong>등록했는데 AI 도구가 Relio를 쓰지 않습니다.</strong> 등록은 새로 켠 AI 도구부터 보입니다. AI 도구를 끄고 다시 켜세요. <code>relio</code>가 PATH에 없다면 <a href="#relio가-path에-없을-때">relio가 PATH에 없을 때</a>처럼 전체 경로로 등록합니다.</p><p><strong>홈 폴더에서 켰더니 모델 목록이 비어 있습니다.</strong> 홈 폴더는 통째로 허락하지 않으므로 Relio에 열린 파일만 보입니다. 모델이 있는 프로젝트 폴더에서 다시 켜거나 <code>--root</code>로 등록하세요. <a href="#ai가-볼-수-있는-파일">AI가 볼 수 있는 파일</a></p><h2 id="관련-쪽" tabindex="-1">관련 쪽 <a class="header-anchor" href="#관련-쪽" aria-label="Permalink to &quot;관련 쪽&quot;">​</a></h2><ul><li><a href="/relio/features/cli">명령줄</a> — <code>relio</code>를 PATH에 넣기, 다른 명령</li><li><a href="/relio/features/git#합치기">Git과 합치기 › 합치기</a> — 합치기 탭에서 고르고 적용하기</li><li><a href="/relio/features/preferences#일반">환경 설정 › 일반</a> — AI 변경 반영 방식</li><li><a href="/relio/features/troubleshooting">도움말과 문제 해결</a> — 사용 설명서, Relio 정보, 내 정보가 저장되는 곳</li></ul>',85)])])}const _=o(h,[["render",u]]);export{f as __pageData,_ as default};
